    var CSS = "/* =====================================================================\n   WorkBuddy · 有风 (Youfeng) — DSH client skin\n   Palette and imagery ported from the WorkBuddy 5.9.3 appearance pack\n   \"workbuddy-skin-green\" (forest-green / 有风).\n   ===================================================================== */\n\n:root {\n  --wf-page: #f6f8f5;\n  --wf-card: #ffffff;\n  --wf-tint: #e8f0e9;\n  --wf-sidebar: #e3ece4;\n  --wf-line: #dce7dd;\n  --wf-line-strong: #c4dbc5;\n  --wf-ink: #12261a;\n  --wf-brand: #3c8c4e;\n  --wf-brand-deep: #256d37;\n}\n\nhtml {\n  color-scheme: light !important;\n  background: var(--wf-page) !important;\n}\n\nbody {\n  background: var(--wf-page) !important;\n  color: #12261ae6;\n}\n\n#root {\n  position: relative;\n  z-index: 1;\n}\n\n/* ---------------------------------------------------------------------\n   Wallpaper scene — only on the empty / new-session surface, matching\n   WorkBuddy's home background. Chat pages stay on the pale paper tone.\n   --------------------------------------------------------------------- */\n.wf-scene {\n  position: fixed;\n  inset: 0;\n  z-index: 0;\n  overflow: hidden;\n  pointer-events: none;\n  opacity: 0;\n  background: var(--wf-page);\n  transition: opacity 420ms ease;\n}\n\nbody.wf-home .wf-scene {\n  opacity: 1;\n}\n\n.wf-scene-bg {\n  position: absolute;\n  inset: 0;\n  background-image: url(\"data:image/webp;base64,\");\n  background-size: cover;\n  background-position: center 58%;\n  background-repeat: no-repeat;\n}\n\n.wf-scene-bg::after {\n  content: \"\";\n  position: absolute;\n  inset: 0;\n  background:\n    linear-gradient(180deg, rgba(255, 255, 255, 0.12) 0%, rgba(255, 255, 255, 0) 32%, rgba(246, 248, 245, 0.16) 100%),\n    radial-gradient(120% 80% at 50% 28%, rgba(255, 255, 255, 0.3), rgba(255, 255, 255, 0) 62%);\n}\n\n.wf-scene-cat {\n  position: absolute;\n  right: clamp(48px, 8.5vw, 150px);\n  bottom: clamp(150px, 22vh, 260px);\n  width: clamp(128px, 15vw, 230px);\n  height: auto;\n  filter: drop-shadow(0 18px 24px rgba(18, 38, 26, 0.16));\n  opacity: 0.96;\n}\n\n.wf-scene-quote {\n  position: absolute;\n  left: 0;\n  right: 0;\n  bottom: 14px;\n  text-align: center;\n  color: #ffffff;\n  font-size: 12px;\n  line-height: 18px;\n  letter-spacing: 0.08em;\n  text-shadow: 0 3px 10px rgba(18, 38, 26, 0.38);\n  opacity: 0.92;\n}\n\n/* ---------------------------------------------------------------------\n   App frame / columns\n   --------------------------------------------------------------------- */\n#root > [data-slot=\"root\"] > [class*=\"_frame\"] {\n  background: transparent !important;\n}\n\n#root [class*=\"_sidebarCol\"] {\n  background: var(--wf-sidebar) !important;\n  border-right: 1px solid #d5e5d6 !important;\n}\n\n#root [class*=\"_centerCol\"] {\n  background: transparent !important;\n}\n\n#root [class*=\"_rightbarCol\"] {\n  background: var(--wf-page) !important;\n  border-left: 1px solid var(--wf-line) !important;\n}\n\n[data-windows-titlebar] #root > [data-slot=\"root\"] > [class*=\"_frame\"] {\n  background: transparent !important;\n}\n\n[data-windows-titlebar] #root > [data-slot=\"root\"] > [class*=\"_frame\"]::before {\n  background: var(--wf-sidebar) !important;\n}\n\n[data-windows-titlebar] #root [class*=\"_centerCol\"] {\n  background: transparent !important;\n}\n\n/* ---------------------------------------------------------------------\n   Sidebar surfaces\n   --------------------------------------------------------------------- */\n[data-slot=\"sidebar\"] > [class*=\"_root\"] {\n  background: transparent !important;\n}\n\n[data-slot=\"sidebar\"] button:hover {\n  background: #dde8df;\n}\n\n[data-slot=\"sidebar\"] button[class*=\"newSession\"] {\n  background: #f4f8f4 !important;\n  border: 1px solid #d5e5d6 !important;\n  color: #256d37 !important;\n}\n\n[data-slot=\"sidebar\"] button[class*=\"newSession\"]:hover {\n  background: #e8f0e9 !important;\n}\n\n[data-slot=\"sidebar\"] [class*=\"_brandName\"] {\n  color: #21472b !important;\n}\n\n/* ---------------------------------------------------------------------\n   Conversation surface\n   --------------------------------------------------------------------- */\n[data-slot=\"main.conversation\"] > [class*=\"_root\"] {\n  background: transparent !important;\n}\n\n[data-slot=\"main.conversation\"] > [class*=\"_root\"][data-phase=\"active\"] {\n  background: var(--wf-page) !important;\n}\n\n[data-slot=\"main.conversation\"] [class*=\"_header\"] {\n  background: transparent !important;\n  border-bottom-color: rgba(18, 38, 26, 0.08) !important;\n}\n\n[data-slot=\"main.conversation\"] [class*=\"_headerBlank\"] {\n  border-bottom: none !important;\n}\n\n/* Hero / welcome copy */\n[data-slot=\"conversation.hero.brand.mark\"] svg path {\n  fill: #21472b;\n}\n\n[data-slot=\"conversation.hero.brand.mark\"] svg [fill=\"#00c29a\"],\n[data-slot=\"conversation.hero.brand.mark\"] svg [fill=\"#3b82f6\"] {\n  fill: #3c8c4e !important;\n}\n\n/* Composer card */\n[class*=\"uV2eYG_card\"] {\n  background: rgba(255, 255, 255, 0.94) !important;\n  border: 1px solid var(--wf-line) !important;\n  box-shadow:\n    0 24px 48px -32px rgba(18, 38, 26, 0.24),\n    0 2px 6px rgba(18, 38, 26, 0.05) !important;\n  backdrop-filter: blur(14px);\n  -webkit-backdrop-filter: blur(14px);\n}\n\n[class*=\"uV2eYG_hero\"] [class*=\"uV2eYG_card\"] {\n  background: rgba(255, 255, 255, 0.9) !important;\n}\n\n[class*=\"uV2eYG_card\"]:focus-within {\n  border-color: #b7d9bc !important;\n  box-shadow:\n    0 26px 54px -30px rgba(18, 38, 26, 0.26),\n    0 0 0 3px rgba(60, 140, 78, 0.09) !important;\n}\n\n[class*=\"uV2eYG_add\"] {\n  background: #eef5ef !important;\n  color: #256d37 !important;\n}\n\n[class*=\"uV2eYG_add\"]:hover:not(:disabled) {\n  background: #dde8df !important;\n}\n\n/* ---------------------------------------------------------------------\n   Selection, focus, links\n   --------------------------------------------------------------------- */\n::selection {\n  background: rgba(60, 140, 78, 0.22);\n  color: #12261a;\n}\n\na {\n  color: #256d37;\n}\n\n*:focus-visible {\n  outline-color: #3c8c4e !important;\n}\n\n/* ---------------------------------------------------------------------\n   Windows / scrollbars / small chrome\n   --------------------------------------------------------------------- */\n#root > [data-slot=\"root\"] > [class*=\"_handle\"] {\n  background: #d5e5d6 !important;\n}\n\n::-webkit-scrollbar {\n  width: 10px;\n  height: 10px;\n}\n\n::-webkit-scrollbar-thumb {\n  background: rgba(18, 38, 26, 0.18);\n  border-radius: 999px;\n  border: 2px solid transparent;\n  background-clip: padding-box;\n}\n\n::-webkit-scrollbar-thumb:hover {\n  background: rgba(18, 38, 26, 0.3);\n  background-clip: padding-box;\n}\n\n::-webkit-scrollbar-track {\n  background: transparent;\n}\n";
    var CAT = "data:image/webp;base64,";

    var PLUGIN_ID = "dsh-client-ui-skin-workbuddy-youfeng";
    var THEME_SOURCE = "dsh-client-ui-skin-workbuddy-youfeng";
    var STYLE_KEY = "dsh-client-ui-skin-workbuddy-youfeng/theme.css";

    function apply(ctx) {
      var body = document.body;
      body.setAttribute("data-dsh-workbuddy-youfeng", "");

      var style = document.createElement("style");
      style.dataset.plugin = PLUGIN_ID;
      style.dataset.pluginCss = STYLE_KEY;
      style.textContent = CSS;
      document.head.appendChild(style);

      var theme = ctx.theme;
      if (theme === undefined && typeof ctx.get === "function") theme = ctx.get("theme");
      var disposeTokens = null;
      if (theme && typeof theme.overrideTokens === "function") {
        disposeTokens = theme.overrideTokens(THEME_SOURCE, TOKENS);
      }

      var scene = document.createElement("div");
      scene.className = "wf-scene";
      scene.setAttribute("aria-hidden", "true");

      var bg = document.createElement("div");
      bg.className = "wf-scene-bg";

      var cat = document.createElement("img");
      cat.className = "wf-scene-cat";
      cat.alt = "";
      cat.src = CAT;

      var quote = document.createElement("div");
      quote.className = "wf-scene-quote";
      quote.textContent = "窗外有风，心里有光。";

      scene.append(bg, cat, quote);
      body.appendChild(scene);

      function syncScene() {
        var slot = document.querySelector('[data-slot="main.conversation"]');
        var phaseNode = slot ? slot.querySelector("[data-phase]") : null;
        var phase = phaseNode ? phaseNode.getAttribute("data-phase") : null;
        var home = phase === "hero" || phase === "blank" || phase === "engaging";
        body.classList.toggle("wf-home", home);
      }

      syncScene();
      var sceneTimer = setInterval(syncScene, 350);

      ctx.effect(() => () => {
        clearInterval(sceneTimer);
        if (typeof disposeTokens === "function") disposeTokens();
        scene.remove();
        style.remove();
        body.classList.remove("wf-home");
        body.removeAttribute("data-dsh-workbuddy-youfeng");
      }, "ui-skin-workbuddy-youfeng: wallpaper and palette");

      if (document.readyState !== "complete") {
        window.addEventListener("load", syncScene, { once: true });
      }
    }

    exports.apply = apply;
    exports.inject = ["theme"];
